"""Configuration and path discovery for the ZentroMart VoiceOps 2026 Agent."""
import base64
import io
import os
import tempfile
import zipfile
from datetime import date
from pathlib import Path

# Fixed dataset reference date (KB-00.2)
REFERENCE_DATE = date(2026, 10, 20)
REFERENCE_DATE_STR = "2026-10-20"

# Embedded compressed dataset fallback for cloud deployments (e.g. Streamlit Community Cloud)
# where ../Capstone_Project_Dataset_FTTT_2026 is not present on the remote container disk.
_CLOUD_DATASET_B64 = ""


def _materialize_cloud_dataset() -> Path:
    """Extract the embedded dataset into the OS temp directory when running on Streamlit Cloud."""
    target_dir = Path(tempfile.gettempdir()) / "zentromart_cloud_dataset"
    if (target_dir / "kb").is_dir() and (target_dir / "data").is_dir() and (target_dir / "tools" / "tools.py").is_file():
        return target_dir.resolve()
    target_dir.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(_CLOUD_DATASET_B64)
    with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
        for member in zf.infolist():
            parts = Path(member.filename).parts
            if not parts:
                continue
            # Strip top-level Capstone_Project_Dataset_FTTT_2026/ prefix if present
            rel_parts = parts[1:] if parts[0] == "Capstone_Project_Dataset_FTTT_2026" else parts
            if not rel_parts:
                continue
            dest = target_dir.joinpath(*rel_parts)
            if member.is_dir() or member.filename.endswith("/"):
                dest.mkdir(parents=True, exist_ok=True)
            else:
                dest.parent.mkdir(parents=True, exist_ok=True)
                dest.write_bytes(zf.read(member.filename))
    return target_dir.resolve()


def resolve_dataset_dir(explicit_dir: str = None) -> Path:
    """Locate the extracted Capstone_Project_Dataset_FTTT_2026 directory (or auto-provision on Cloud)."""
    candidates = []
    if explicit_dir:
        candidates.append(Path(explicit_dir))
    env_dir = os.environ.get("ZENTROMART_DATASET_DIR") or os.environ.get("DATASET_DIR")
    if env_dir:
        candidates.append(Path(env_dir))

    here = Path(__file__).resolve().parent
    project_root = here.parent
    cwd = Path.cwd()

    for base in (cwd, project_root, project_root.parent, here):
        candidates.append(base)
        candidates.append(base / "Capstone_Project_Dataset_FTTT_2026")
        candidates.append(base / "work_dataset" / "Capstone_Project_Dataset_FTTT_2026")
        candidates.append(base.parent / "Capstone_Project_Dataset_FTTT_2026")
        candidates.append(base.parent / "work_dataset" / "Capstone_Project_Dataset_FTTT_2026")

    for cand in candidates:
        if (cand / "kb").is_dir() and (cand / "data").is_dir() and (cand / "tools" / "tools.py").is_file():
            return cand.resolve()

    return _materialize_cloud_dataset()


